'use strict';

/**
 * Manual smoke test: enqueues ONE row into notification_queue so the running
 * worker sends it over WhatsApp.
 *
 *   npm run send:test -- 0788100001
 *
 * The phone number always comes from argv; nothing real is hardcoded here.
 */

require('dotenv').config();

const pool = require('../src/config/database');

const TEST_MESSAGE =
  'SBMS WhatsApp integration test. This message was generated by the school ' +
  'notification service to verify the queue worker; no action is required.';

async function main() {
  const phone = process.argv[2];

  if (!phone) {
    console.error('Usage: npm run send:test -- <parent_phone>');
    console.error('Example: npm run send:test -- 0788100001');
    process.exitCode = 1;
    await pool.end();
    return;
  }

  const digits = String(phone).replace(/\D/g, '');
  if (digits.length < 10 || digits.length > 15) {
    console.error(`Refusing to enqueue "${phone}": expected 10-15 digits (e.g. 0788100001 or +250788100001).`);
    process.exitCode = 1;
    await pool.end();
    return;
  }

  const [result] = await pool.query(
    `INSERT INTO notification_queue
       (student_id, parent_phone, message, notification_type, dedupe_key, status, attempts, max_attempts, next_attempt_at)
     VALUES (NULL, ?, ?, 'manual_test', ?, 'pending', 0, 3, NOW())`,
    [phone, TEST_MESSAGE, `manual-test-${Date.now()}`]
  );

  console.log(`Enqueued test notification. Queue id: ${result.insertId}`);
  console.log('The running worker will pick it up within a few seconds.');

  await pool.end();
}

main().catch(async (err) => {
  console.error('Failed to enqueue test row:', err.message);
  process.exitCode = 1;
  await pool.end().catch(() => {});
});
